CREATE TABLE IF NOT EXISTS drafts (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, content TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, username TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS attempts (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media (path TEXT PRIMARY KEY, size INTEGER NOT NULL, mime TEXT NOT NULL, sha TEXT NOT NULL, complete INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS chunks (path TEXT NOT NULL REFERENCES media(path), idx INTEGER NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(path,idx));
CREATE TABLE IF NOT EXISTS publishing (id INTEGER PRIMARY KEY CHECK(id=1), lease TEXT, expires INTEGER NOT NULL DEFAULT 0, commit_sha TEXT, revision INTEGER, username TEXT);
INSERT OR IGNORE INTO publishing(id) VALUES(1);
